import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Alert } from 'react-bootstrap';
import axios from 'axios';

const Team = () => {
  const [team, setTeam] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchTeam();
  }, []);

  const fetchTeam = async () => {
    try {
      const res = await axios.get('/api/admin/team');
      setTeam(res.data);
      setLoading(false);
    } catch (err) {
      setError('Failed to load team members');
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Container className="py-5">
        <div className="text-center">Loading...</div>
      </Container>
    );
  }

  return (
    <Container className="py-5">
      <h1 className="text-center mb-4">Our Team</h1>

      {error && <Alert variant="danger">{error}</Alert>}

      {team.length === 0 ? (
        <Alert variant="info" className="text-center">
          Team members will be added soon.
        </Alert>
      ) : (
        <Row>
          {team.map((member) => (
            <Col lg={3} md={4} key={member.id} className="mb-4">
              <Card className="h-100 shadow-sm text-center">
                {member.photo_url ? (
                  <Card.Img
                    variant="top"
                    src={member.photo_url.startsWith('/') ? member.photo_url : `/${member.photo_url}`}
                    alt={member.name}
                    style={{ height: '650px', objectFit: 'contain' }}
                    onError={(e) => {
                      e.target.style.display = 'none';
                      e.target.nextElementSibling.style.display = 'flex';
                    }}
                  />
                ) : (
                  <div
                    style={{
                      height: '650px',
                      background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: 'white',
                      fontSize: '4rem'
                    }}
                  >
                    <i className="fas fa-user"></i>
                  </div>
                )}
                <Card.Body className="d-flex flex-column">
                  <Card.Title className="h5">{member.name}</Card.Title>
                  <Card.Text className="text-muted">{member.role}</Card.Text>
                  <div className="mt-auto">
                    <p className="mb-0"><strong>Student ID:</strong> {member.student_id}</p>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      )}
    </Container>
  );
};

export default Team;
