import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Alert } from 'react-bootstrap';
import axios from 'axios';

const Gallery = () => {
  const [gallery, setGallery] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchGallery();
  }, []);

  const fetchGallery = async () => {
    try {
      const res = await axios.get('/api/admin/gallery');
      setGallery(res.data);
      setLoading(false);
    } catch (err) {
      setError('Failed to load gallery');
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Container className="py-5">
        <div className="text-center">Loading...</div>
      </Container>
    );
  }

  return (
    <Container className="py-5">
      <h1 className="text-center mb-4">Event Gallery</h1>

      {error && <Alert variant="danger">{error}</Alert>}

      {gallery.length === 0 ? (
        <Alert variant="info" className="text-center">
          Gallery images will be added after events.
        </Alert>
      ) : (
        <Row>
          {gallery.map((image) => (
            <Col lg={4} md={6} key={image.id} className="mb-4">
              <Card className="shadow">
                <Card.Img
                  variant="top"
                  src={image.image_url}
                  alt={image.event_name}
                  style={{ height: '250px', objectFit: 'cover' }}
                />
                <Card.Body>
                  <Card.Title className="h6">{image.event_name}</Card.Title>
                  <Card.Text className="text-muted small">
                    {new Date(image.uploaded_at).toLocaleDateString()}
                  </Card.Text>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      )}
    </Container>
  );
};

export default Gallery;
