import React from 'react';
import { Navbar, Nav, Container, Button } from 'react-bootstrap';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';

const NavigationBar = () => {
  const { user, logout, loading } = useAuth();
  const navigate = useNavigate();

  const handleGoogleLogin = () => {
    window.location.href = '/api/auth/google';
  };

  if (loading) {
    return (
      <Navbar bg="dark" variant="dark" expand="lg" sticky="top">
        <Container>
          <Navbar.Brand>
            <img
              src="/logo.jpg"
              width="30"
              height="30"
              className="d-inline-block align-top me-2"
              alt="Chalchitra Logo"
            />
            Chalchitra Series
          </Navbar.Brand>
        </Container>
      </Navbar>
    );
  }

  return (
    <Navbar bg="dark" variant="dark" expand="lg" sticky="top">
      <Container>
        <Navbar.Brand as={Link} to="/">
          <img
            src="/logo.jpg"
            width="30"
            height="30"
            className="d-inline-block align-top me-2"
            alt="Chalchitra Logo"
          />
          Chalchitra Series
        </Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav" />
        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="me-auto">
            <Nav.Link as={Link} to="/upcoming-movies">Upcoming Movies</Nav.Link>
            <Nav.Link as={Link} to="/past-movies">Past Movies</Nav.Link>
            <Nav.Link as={Link} to="/gallery">Gallery</Nav.Link>
            <Nav.Link as={Link} to="/team">Team</Nav.Link>
            <Nav.Link as={Link} to="/contact">Contact Us</Nav.Link>
          </Nav>
          <Nav className="ms-auto">
            {user ? (
              <>
                <Nav.Link as={Link} to="/my-bookings">My Bookings</Nav.Link>
                {(user.code_scanner || user.team_scanner) && (
                  <Nav.Link as={Link} to="/scanner" className="text-warning">
                    <i className="fas fa-qrcode me-1"></i>
                    QR Scanner
                  </Nav.Link>
                )}
                {user.is_admin && (
                  <Nav.Link as={Link} to="/admin">Admin</Nav.Link>
                )}
                <Navbar.Text className="me-3">
                  Welcome, {user.name}
                </Navbar.Text>
                <Button variant="outline-light" onClick={logout}>
                  Logout
                </Button>
              </>
            ) : (
              <div className="d-flex align-items-center">
                <Button variant="outline-light" onClick={handleGoogleLogin} className="me-3">
                  <img
                    src="https://developers.google.com/identity/images/g-logo.png"
                    alt="Google"
                    width="20"
                    height="20"
                    className="me-2"
                  />
                  Login with Google
                </Button>
                <img
                  src="/iitjammu-logo.png"
                  alt="IIT Jammu"
                  style={{ marginLeft: 'auto', maxHeight: '50px', maxWidth: '150px' }}
                />
              </div>
            )}
          </Nav>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
};

export default NavigationBar;
