import React, { useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, useNavigate } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import './App.css';

// Contexts
import { AuthProvider } from './contexts/AuthContext';

// Components
import Navbar from './components/Navbar';
import Footer from './components/Footer';

// Pages
import Home from './pages/Home';
import UpcomingMovies from './pages/UpcomingMovies';
import PastMovies from './pages/PastMovies';
import Gallery from './pages/Gallery';
import Team from './pages/Team';
import Contact from './pages/Contact';
import Booking from './pages/Booking';
import MyBookings from './pages/MyBookings';
import AdminPanel from './pages/AdminPanel';
import TeamScanner from './pages/TeamScanner';
import Login from './pages/Login';

// GitHub Pages routing handler
function GitHubPagesRouter() {
  const navigate = useNavigate();

  useEffect(() => {
    // Handle GitHub Pages routing
    const handleGitHubPagesRouting = () => {
      const path = window.location.pathname;
      const search = window.location.search;

      // Check if this is a GitHub Pages redirect (has ?/ in search)
      if (search && search.startsWith('?/')) {
        const redirectPath = search.substring(1); // Remove the ?
        const newPath = redirectPath.replace(/\/$/, ''); // Remove trailing slash
        navigate(newPath, { replace: true });
      }
    };

    handleGitHubPagesRouting();
  }, [navigate]);

  return null;
}

function AppContent() {
  return (
    <div className="App">
      <GitHubPagesRouter />
      <Navbar />
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/upcoming-movies" element={<UpcomingMovies />} />
        <Route path="/past-movies" element={<PastMovies />} />
        <Route path="/gallery" element={<Gallery />} />
        <Route path="/team" element={<Team />} />
        <Route path="/contact" element={<Contact />} />
        <Route path="/booking/:movieId" element={<Booking />} />
        <Route path="/my-bookings" element={<MyBookings />} />
        <Route path="/admin" element={<AdminPanel />} />
        <Route path="/scanner" element={<TeamScanner />} />
        <Route path="/login" element={<Login />} />
      </Routes>
      <Footer />
    </div>
  );
}

function App() {
  return (
    <AuthProvider>
      <Router>
        <AppContent />
      </Router>
    </AuthProvider>
  );
}

export default App;
