import React, { useState, useEffect, useRef } from 'react';
import { Modal, Button, Alert, Card } from 'react-bootstrap';
import { Html5QrcodeScanner } from 'html5-qrcode';

const styles = `
  @keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
  }
`;

const QRScanner = ({ onScan, onClose }) => {
  const [scanResult, setScanResult] = useState('');
  const [error, setError] = useState('');
  const [showResult, setShowResult] = useState(false);
  const [scanStatus, setScanStatus] = useState(null); // { valid: boolean, data: object }
  const [lastScanResult, setLastScanResult] = useState(null); // Keep last scan result visible
  const [showScanAnother, setShowScanAnother] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false); // Prevent multiple scans
  const [scannerActive, setScannerActive] = useState(true); // Control scanner state
  const scannerRef = useRef(null);

  useEffect(() => {
    // Initialize QR scanner when component mounts
    initializeScanner();

    return () => {
      // Cleanup scanner when component unmounts
      if (scannerRef.current) {
        scannerRef.current.clear().catch(console.error);
      }
    };
  }, []);

  const initializeScanner = () => {
    // Create scanner instance
    const scanner = new Html5QrcodeScanner('qr-reader', {
      fps: 10,
      qrbox: { width: 250, height: 250 },
      aspectRatio: 1.0,
      showTorchButtonIfSupported: true,
      showZoomSliderIfSupported: true,
      defaultZoomValueIfSupported: 2,
    });

    scannerRef.current = scanner;

    // Success callback
    const onScanSuccess = async (decodedText, decodedResult) => {
      console.log('QR Code scanned:', decodedText);

      // Prevent multiple scans if already processing
      if (isProcessing) {
        console.log('Already processing a scan, ignoring...');
        return;
      }

      setIsProcessing(true);
      setScannerActive(false); // Deactivate scanner

      // Completely destroy the scanner to prevent any further scanning
      if (scannerRef.current) {
        scannerRef.current.clear().catch(console.error);
        scannerRef.current = null;
      }

      // Call parent callback to process the scan
      if (onScan) {
        try {
          // Show processing status
          setScanStatus({ processing: true });

          const result = await onScan(decodedText);

          // Show result status
          setScanStatus({
            valid: result?.allowed || false,
            data: result,
            processing: false
          });

          // Store last scan result
          setLastScanResult({
            valid: result?.allowed || false,
            data: result
          });

          // Auto-hide popup after 1 second and show scan another button
          setTimeout(() => {
            setScanStatus(null);
            setShowScanAnother(true);
            setIsProcessing(false);
          }, 1000);

        } catch (error) {
          setScanStatus({
            valid: false,
            error: true,
            data: null,
            processing: false
          });

          // Store last scan result (error case)
          setLastScanResult({
            valid: false,
            error: true,
            data: null
          });

          // Auto-hide popup after 1 second and show scan another button
          setTimeout(() => {
            setScanStatus(null);
            setShowScanAnother(true);
            setIsProcessing(false);
          }, 1000);
        }
      }
    };

    // Error callback
    const onScanError = (errorMessage) => {
      // Ignore scan errors during normal operation
      if (!errorMessage.includes('NotFoundException')) {
        console.warn('QR Scan error:', errorMessage);
      }
    };

    // Render scanner
    scanner.render(onScanSuccess, onScanError);
  };

  const handleManualInput = () => {
    const manualCode = prompt('Enter QR Code manually:');
    if (manualCode && manualCode.trim()) {
      setScanResult(manualCode.trim());
      setShowResult(true);

      if (onScan) {
        onScan(manualCode.trim());
      }
    }
  };

  const resetScanner = () => {
    setScanResult('');
    setError('');
    setShowResult(false);
    setShowScanAnother(false); // Hide the scan another button

    // Clear any existing scanner
    if (scannerRef.current) {
      scannerRef.current.clear().catch(console.error);
    }

    // Small delay to ensure cleanup is complete
    setTimeout(() => {
      initializeScanner();
    }, 100);
  };

  const closeScanner = () => {
    if (scannerRef.current) {
      scannerRef.current.clear().catch(console.error);
    }
    onClose();
  };

  return (
    <>
      <style>{styles}</style>
      <Modal show={true} onHide={closeScanner} size="lg" centered>
        <Modal.Header closeButton>
          <Modal.Title className="text-center w-100">
            <i className="fas fa-qrcode me-2"></i>
            🎫 QR Code Scanner
          </Modal.Title>
        </Modal.Header>
      <Modal.Body className="text-center position-relative">
        {/* Status Overlay */}
        {scanStatus && (
          <div
            style={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: scanStatus.processing ? 'rgba(0,0,0,0.8)' : scanStatus.valid ? 'rgba(40, 167, 69, 0.95)' : 'rgba(220, 53, 69, 0.95)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 9999,
              animation: 'fadeIn 0.3s ease-in-out'
            }}
          >
            <div className="text-center text-white p-4">
              {scanStatus.processing ? (
                <>
                  <div className="spinner-border text-white mb-3" role="status" style={{ width: '3rem', height: '3rem' }}>
                    <span className="visually-hidden">Processing...</span>
                  </div>
                  <h3 className="mb-2">Processing Ticket...</h3>
                  <p className="mb-0">Validating QR code...</p>
                </>
              ) : scanStatus.valid ? (
                <>
                  <i className="fas fa-check-circle fa-4x mb-3"></i>
                  <h2 className="mb-3 fw-bold">✓ VALID TICKET</h2>
                  <div className="bg-white bg-opacity-20 rounded p-3 mb-2">
                    <p className="mb-1 fw-bold">{scanStatus.data?.student_name}</p>
                    <p className="mb-1">{scanStatus.data?.student_email}</p>
                    <p className="mb-0 small">{scanStatus.data?.movie_name}</p>
                  </div>
                  <p className="small opacity-75">Entry Allowed</p>
                </>
              ) : (
                <>
                  <i className="fas fa-times-circle fa-4x mb-3"></i>
                  <h2 className="mb-3 fw-bold">✗ INVALID TICKET</h2>
                  <div className="bg-white bg-opacity-20 rounded p-3 mb-2">
                    {scanStatus.data?.student_name && (
                      <>
                        <p className="mb-1 fw-bold">{scanStatus.data.student_name}</p>
                        <p className="mb-1">{scanStatus.data.student_email}</p>
                        <p className="mb-0 small">{scanStatus.data.movie_name}</p>
                      </>
                    )}
                  </div>
                  <p className="small opacity-75">
                    {scanStatus.data?.validity_status || 'Entry Denied'}
                  </p>
                </>
              )}
            </div>
          </div>
        )}

        {!showResult ? (
          <>
            {/* QR Scanner */}
            <div className="mb-4">
              <Card className="border-0 shadow-sm">
                <Card.Body className="p-3">
                  <div
                    id="qr-reader"
                    style={{
                      width: '100%',
                      maxWidth: '400px',
                      margin: '0 auto'
                    }}
                  ></div>
                </Card.Body>
              </Card>
            </div>

            {/* Instructions */}
            <div className="mb-3">
              <i className="fas fa-mobile-alt fa-2x text-primary mb-3"></i>
              <h5>Scan Student Ticket</h5>
              <p className="text-muted mb-0">
                Point your camera at the QR code on the student's mobile ticket
              </p>
            </div>

            {/* Error Messages */}
            {error && (
              <Alert variant="danger" className="mt-3">
                <i className="fas fa-exclamation-triangle me-2"></i>
                {error}
              </Alert>
            )}

            {/* Last Scan Result */}
            {showScanAnother && lastScanResult && (
              <div className="mt-3 p-3 bg-light rounded">
                <h6 className="mb-2">
                  <i className={`fas ${lastScanResult.valid ? 'fa-check-circle text-success' : 'fa-times-circle text-danger'} me-2`}></i>
                  Last Scanned Ticket
                </h6>
                <div className="text-start">
                  {lastScanResult.valid ? (
                    <>
                      <p className="mb-1 fw-bold text-success">✓ VALID - Entry Allowed</p>
                      <p className="mb-1"><strong>Name:</strong> {lastScanResult.data?.student_name}</p>
                      <p className="mb-1"><strong>Email:</strong> {lastScanResult.data?.student_email}</p>
                      <p className="mb-0"><strong>Movie:</strong> {lastScanResult.data?.movie_name}</p>
                    </>
                  ) : (
                    <>
                      <p className="mb-1 fw-bold text-danger">✗ INVALID - Entry Denied</p>
                      {lastScanResult.data?.student_name && (
                        <>
                          <p className="mb-1"><strong>Name:</strong> {lastScanResult.data.student_name}</p>
                          <p className="mb-1"><strong>Email:</strong> {lastScanResult.data.student_email}</p>
                          <p className="mb-0"><strong>Movie:</strong> {lastScanResult.data.movie_name}</p>
                        </>
                      )}
                      {lastScanResult.data?.validity_status && (
                        <p className="mb-0 text-muted small">Reason: {lastScanResult.data.validity_status}</p>
                      )}
                    </>
                  )}
                </div>
              </div>
            )}

            {/* Scan Another Button */}
            {showScanAnother && (
              <div className="mt-3">
                <Button
                  onClick={() => {
                    setShowScanAnother(false);
                    setLastScanResult(null); // Clear last result when starting new scan
                    resetScanner();
                  }}
                  variant="success"
                  size="lg"
                  className="px-4"
                >
                  <i className="fas fa-qrcode me-2"></i>
                  Scan Another Ticket
                </Button>
              </div>
            )}

            {/* Action Buttons */}
            <div className="d-flex gap-2 justify-content-center flex-wrap mt-3">
              <Button onClick={handleManualInput} variant="outline-secondary">
                <i className="fas fa-keyboard me-2"></i>
                Manual Input
              </Button>
            </div>

            <div className="mt-3">
              <small className="text-muted">
                <i className="fas fa-info-circle me-1"></i>
                Make sure the QR code is well-lit and clearly visible in the scan area
              </small>
            </div>

            {/* Troubleshooting Tips */}
            <div className="mt-3 p-3 bg-light rounded">
              <h6 className="mb-2"><i className="fas fa-tools me-2"></i>Troubleshooting:</h6>
              <small className="text-muted">
                • Allow camera permissions when prompted<br />
                • Check browser settings for camera access<br />
                • Try refreshing the page<br />
                • Use manual input as fallback
              </small>
            </div>
          </>
        ) : (
          <div>
            <div className="mb-4">
              <i className="fas fa-check-circle fa-4x text-success mb-3"></i>
              <h4>QR Code Scanned Successfully!</h4>
              <p className="text-muted">Processing ticket validation...</p>
              <div className="mt-3 p-3 bg-light rounded">
                <small className="text-muted">Scanned Code:</small>
                <br />
                <code className="text-break">{scanResult}</code>
              </div>
            </div>

            <div className="d-flex gap-2 justify-content-center">
              <Button onClick={resetScanner} variant="outline-primary">
                <i className="fas fa-redo me-2"></i>
                Scan Another
              </Button>
              <Button onClick={closeScanner} variant="secondary">
                <i className="fas fa-times me-2"></i>
                Close Scanner
              </Button>
            </div>
          </div>
        )}
      </Modal.Body>
    </Modal>
    </>
  );
};

export default QRScanner;
