import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Alert, Modal } from 'react-bootstrap';
import axios from 'axios';
import QRCode from 'qrcode';

const MyBookings = () => {
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selectedBooking, setSelectedBooking] = useState(null);
  const [showTicketModal, setShowTicketModal] = useState(false);


  useEffect(() => {
    fetchBookings();
  }, []);

  const fetchBookings = async () => {
    try {
      const res = await axios.get('/api/bookings/my');
      setBookings(res.data);
      setLoading(false);
    } catch (err) {
      setError('Failed to load bookings');
      setLoading(false);
    }
  };

  const handleViewTicket = async (booking) => {
    setSelectedBooking(booking);

    // Generate QR code for bookings with UUID-only qr_codes
    if (booking.qr_code && !booking.qr_code.startsWith('data:')) {
      try {
        const qrData = {
          booking_id: booking.id,
          user_name: booking.name || 'Student',
          user_email: booking.email || '',
          user_id: booking.user_id,
          movie_title: booking.title,
          movie_date: booking.date,
          venue: booking.venue,
          selected_seats: booking.selected_seats ? JSON.parse(booking.selected_seats) : [],
          timestamp: new Date().toISOString()
        };

        const qrDataURL = await QRCode.toDataURL(JSON.stringify(qrData));
        setSelectedBooking({...booking, qr_code: qrDataURL});
      } catch (err) {
        console.error('Error generating QR code:', err);
      }
    }

    setShowTicketModal(true);
  };

  const downloadTicket = () => {
    const ticketData = {
      movie: selectedBooking.title,
      date: selectedBooking.date,
      venue: selectedBooking.venue,
      booking_id: selectedBooking.id,
      qr_code: selectedBooking.qr_code,
      num_people: selectedBooking.num_people
    };
    const dataStr = JSON.stringify(ticketData, null, 2);
    const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
    const exportFileDefaultName = `ticket-${selectedBooking.id}.json`;
    const linkElement = document.createElement('a');
    linkElement.setAttribute('href', dataUri);
    linkElement.setAttribute('download', exportFileDefaultName);
    linkElement.click();
  };

  if (loading) {
    return (
      <Container className="py-5">
        <div className="text-center">Loading...</div>
      </Container>
    );
  }

  return (
    <Container className="py-5">
      <h1 className="text-center mb-4">My Bookings</h1>

      {error && <Alert variant="danger">{error}</Alert>}

      {bookings.length === 0 ? (
        <Alert variant="info" className="text-center">
          You haven't booked any tickets yet.
        </Alert>
      ) : (
        <Row>
          {bookings.map((booking) => (
            <Col lg={6} key={booking.id} className="mb-4">
              <Card className="h-100 shadow">
                <Card.Body className="d-flex flex-column">
                  <Card.Title className="h5">{booking.title}</Card.Title>
                  <div className="mb-3">
                    <Row>
                      <Col xs={6}>
                        <strong>Date:</strong><br />
                        {new Date(booking.date).toLocaleDateString()}
                      </Col>
                      <Col xs={6}>
                        <strong>Venue:</strong><br />
                        {booking.venue}
                      </Col>
                    </Row>
                  </div>
                  <div className="mb-3">
                    <p><strong>Booking ID:</strong> {booking.id}</p>
                    {booking.selected_seats && (
                      <p><strong>Seats:</strong> {JSON.parse(booking.selected_seats).join(', ')}</p>
                    )}
                    <p><strong>Total Price:</strong> ₹{booking.total_price}</p>
                    <p><strong>Status:</strong>
                      <span className={`ms-2 ${booking.is_used ? 'text-danger' : 'text-success'}`}>
                        {booking.is_used ? 'Used' : 'Valid'}
                      </span>
                    </p>
                  </div>
                  <div className="mt-auto">
                    <Button
                      variant="primary"
                      className="w-100 mb-2"
                      onClick={() => handleViewTicket(booking)}
                    >
                      View Ticket
                    </Button>
                    {!booking.is_used && (
                      <small className="text-muted">
                        Show this QR code at the entry for validation
                      </small>
                    )}
                  </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      )}

      {/* Ticket Modal */}
      <Modal show={showTicketModal} onHide={() => setShowTicketModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Ticket Details</Modal.Title>
        </Modal.Header>
        <Modal.Body className="text-center">
          <div className="border p-4 my-3">
            <img src="/logo.jpg" alt="Logo" className="mb-3" style={{maxWidth: '100px'}} />
            <h5>{selectedBooking?.title}</h5>
            <p><strong>Date:</strong> {selectedBooking ? new Date(selectedBooking.date).toLocaleDateString() : ''}</p>
            <p><strong>Venue:</strong> {selectedBooking?.venue}</p>
            <p><strong>Booking ID:</strong> {selectedBooking?.id}</p>
            {selectedBooking?.selected_seats && (
              <p><strong>Seats:</strong> {JSON.parse(selectedBooking.selected_seats).join(', ')}</p>
            )}
            <p><strong>Status:</strong>
              <span className={`ms-2 ${selectedBooking?.is_used ? 'text-danger' : 'text-success'}`}>
                {selectedBooking?.is_used ? 'Used' : 'Valid'}
              </span>
            </p>
            {selectedBooking?.qr_code && (
              <div className="my-3">
                <div className="border p-3 bg-light">
                  <p className="mb-2 small text-muted">
                    {selectedBooking.is_used ? 'QR Code (Already Used)' : 'Scan this QR code at entry for validation'}
                  </p>
                  <img
                    src={selectedBooking.qr_code}
                    alt="QR Code"
                    style={{maxWidth: '200px', height: '200px'}}
                    className={selectedBooking.is_used ? 'opacity-50' : ''}
                  />
                  {selectedBooking.is_used && (
                    <p className="mt-2 small text-danger">
                      <i className="fas fa-exclamation-triangle me-1"></i>
                      This ticket has already been used for entry
                    </p>
                  )}
                </div>
              </div>
            )}
          </div>
          <Button variant="primary" onClick={downloadTicket} className="me-2">
            Download Ticket
          </Button>
        </Modal.Body>
      </Modal>
    </Container>
  );
};

export default MyBookings;
