import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Alert } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import axios from 'axios';

const UpcomingMovies = () => {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchMovies();
  }, []);

  const fetchMovies = async () => {
    try {
      const res = await axios.get('/api/movies/upcoming');
      setMovies(res.data);
      setLoading(false);
    } catch (err) {
      setError('Failed to load movies');
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Container className="py-5">
        <div className="text-center">Loading...</div>
      </Container>
    );
  }

  return (
    <Container className="py-5">
      <h1 className="text-center mb-4">Upcoming Movies</h1>

      {error && <Alert variant="danger">{error}</Alert>}

      {movies.length === 0 ? (
        <Alert variant="info" className="text-center">
          No upcoming movies at the moment. Check back later!
        </Alert>
      ) : (
        <Row>
          {movies.map((movie) => (
            <Col lg={3} md={4} key={movie.id} className="mb-4">
              <Card className="h-100 shadow">
                {movie.poster_url ? (
                  <Card.Img
                    variant="top"
                    src={movie.poster_url.startsWith('/') ? movie.poster_url : `/${movie.poster_url}`}
                    alt={movie.title}
                    style={{ height: '650px', objectFit: 'contain' }}
                    onError={(e) => {
                      e.target.style.display = 'none';
                      e.target.nextElementSibling.style.display = 'flex';
                    }}
                  />
                ) : (
                  <div
                    style={{
                      height: '650px',
                      background: 'linear-gradient(135deg, #f093fb 0%, #f5576c 100%)',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: 'white',
                      fontSize: '4rem'
                    }}
                  >
                    <i className="fas fa-film"></i>
                  </div>
                )}
                <Card.Body className="d-flex flex-column">
                  <Card.Title className="h5">{movie.title}</Card.Title>
                  <Card.Text className="flex-grow-1">{movie.description}</Card.Text>
                    <div className="mt-auto">
                      <Row className="mb-2">
                        <Col xs={6}>
                          <strong>Date:</strong><br />
                          {new Date(movie.date).toLocaleDateString()}
                        </Col>
                        <Col xs={6}>
                          <strong>Venue:</strong><br />
                          {movie.venue}
                        </Col>
                      </Row>
                      <Button as={Link} to={`/booking/${movie.id}`} variant="primary" className="w-100">
                        Book Tickets
                      </Button>
                    </div>
                </Card.Body>
              </Card>
            </Col>
          ))}
        </Row>
      )}
    </Container>
  );
};

export default UpcomingMovies;
